import{_ as a,c as e,o as i,a2 as n}from"./chunks/framework.QTfwLiL8.js";const u=JSON.parse('{"title":"Introducing Automated Credential Rotation","description":"","frontmatter":{"aliases":["/blog/2026/01/28/introducing-automated-credential-rotation"],"authors":[{"avatar":"https://avatars.githubusercontent.com/AleksandarSavchev","login":"AleksandarSavchev","name":"Aleksandar Savchev"}],"github_repo":"https://github.com/gardener/documentation","github_subdir":"website/blog/2026/01","linkTitle":"Introducing Automated Credential Rotation","newsSubtitle":"January 28, 2026","params":{"github_branch":"master"},"path_base_for_github_subdir":{"from":"content/blog/2026/01/01-28-introducing-automated-credential-rotation.md","to":"01-28-introducing-automated-credential-rotation.md"},"publishdate":"2026-01-28","title":"Introducing Automated Credential Rotation"},"headers":[],"relativePath":"blog/2026/01/01-28-introducing-automated-credential-rotation/index.md","filePath":"blog/2026/01/01-28-introducing-automated-credential-rotation.md","lastUpdated":null}'),s={name:"blog/2026/01/01-28-introducing-automated-credential-rotation/index.md"};function o(r,t,l,d,h,c){return i(),e("div",null,t[0]||(t[0]=[n(`<h1 id="introducing-automated-credential-rotation" tabindex="-1">Introducing Automated Credential Rotation <a class="header-anchor" href="#introducing-automated-credential-rotation" aria-label="Permalink to &quot;Introducing Automated Credential Rotation&quot;">​</a></h1><p>Maintaining a strong security posture is crucial for any Kubernetes environment. A key aspect of this is the regular rotation of credentials. To simplify this essential task and reduce operational overhead, Gardener now supports the automatic rotation of several critical credentials during a <code>Shoot</code> cluster&#39;s maintenance window.</p><h3 id="enhanced-security-effortlessly" tabindex="-1">Enhanced Security, Effortlessly <a class="header-anchor" href="#enhanced-security-effortlessly" aria-label="Permalink to &quot;Enhanced Security, Effortlessly&quot;">​</a></h3><p>Previously, users were responsible for manually triggering credential rotations. With this new enhancement, you can now configure your <code>Shoot</code> clusters to automatically handle the rotation of:</p><ul><li><strong>SSH keypair</strong> for worker nodes</li><li><strong>Observability passwords</strong></li><li><strong>etcd encryption key</strong></li></ul><p>This ensures that credentials are rotated consistently and on schedule, bolstering the security of your clusters without requiring manual intervention.</p><h3 id="how-to-enable-automatic-rotation" tabindex="-1">How to Enable Automatic Rotation <a class="header-anchor" href="#how-to-enable-automatic-rotation" aria-label="Permalink to &quot;How to Enable Automatic Rotation&quot;">​</a></h3><p>You can opt-in to this feature by defining the desired rotation schedule in the <code>Shoot</code> manifest under the <code>.spec.maintenance.autoRotation</code> field.</p><p>During the daily maintenance window, the <code>gardener-controller-manager</code> will check if the configured rotation period has passed since the last successful rotation for a given credential. If it has, a new rotation will be initiated automatically.</p><p>Here is an example of how to configure it:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">spec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  maintenance</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    autoRotation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      credentials</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # Set this field to enable automatic rotation for observability credentials</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        observability</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">          rotationPeriod</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">168h</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Rotates every 7 days</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # Set this field to enable automatic rotation for the SSH keypair</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        sshKeypair</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">          rotationPeriod</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">168h</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Rotates every 7 days</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # Set this field to enable automatic rotation for the etcd encryption key</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        etcdEncryptionKey</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">          rotationPeriod</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">168h</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Rotates every 7 days</span></span></code></pre></div><p>If you specify a credential type (like <code>observability: {}</code>) but omit the <code>rotationPeriod</code>, it will default to <code>168h</code> (7 days). The rotation period can be configured to be between 30 minutes and 90 days.</p><p>To disable automatic rotation for a specific credential, you can set its <code>rotationPeriod</code> to <code>0</code>. Manual rotation via annotations remains available if you need to trigger a rotation outside of the scheduled maintenance window.</p><p>This new capability makes it easier than ever to follow security best practices, helping you keep your Gardener-managed Kubernetes clusters secure and up-to-date.</p><h3 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further Reading&quot;">​</a></h3><ul><li><a href="https://youtu.be/2rOOsQWLO_w" target="_blank" rel="noreferrer">Recording of &quot;Automatic Credentials Rotation During Shoot Maintenance&quot;</a></li><li><a href="https://github.com/gardener/gardener/pull/13493" target="_blank" rel="noreferrer">GitHub Pull Request: Add option to automatically rotate credentials in the Maintenance window</a></li></ul>`,16)]))}const k=a(s,[["render",o]]);export{u as __pageData,k as default};
